    // two blocks, matching the game's 16px/block water texture scale.
    uv = vec2(vPos.x + vPos.z + 0.5, 0.5 - vPos.y) * 0.5;
    du = vec2(dx.x + dx.z, -dx.y) * 0.5;
    dv = vec2(dy.x + dy.z, -dy.y) * 0.5;
